(async function () {
	const BASE_URL = "https://p.eagate.573.jp/game/sdvx/vii/playdata/";
	const INDEX_PATH = "index.html";
	const PLAYER_PATH = "profile/index.html";
	const MUSIC_PATH = "musicdata/index.html";
	const MASTER_URL = "https://raw.githubusercontent.com/yuuya1202/sdvx-vf-tool/main/sdvx_master.json";

	const _sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
	const getRandomInt = (min, max) => Math.floor(Math.random() * (max - min) + min);

	const fetchHTML = async (url, referer_url) => {
		const response = await fetch(url, { cache: "no-store", referrer: referer_url, credentials: "include" });
		if (!response.ok) throw new Error(`Network response was not ok: ${response.statusText}`);
		return response.text();
	};

	const getMusicData = async (page) => {
		const url = `${BASE_URL}${MUSIC_PATH}?&sort=0&page=${page}`;
		return fetchHTML(url, BASE_URL + MUSIC_PATH + "?page=1&sort=0");
	};

	// ---- title normalization (must mirror the master-building normalization) ----
	const normTitle = (s) => {
		if (s == null) return "";
		s = String(s).normalize("NFKC").toLowerCase().replace(/\s+/g, "");
		const repl = {
			"\u2019": "'", "\u2018": "'", "\u00b4": "'", "`": "'",
			"\u201c": '"', "\u201d": '"',
			"\uff0d": "-", "\u2015": "-", "\u2014": "-", "\u2010": "-", "\u2011": "-",
			"\uff5e": "~", "\u301c": "~",
			"\uff08": "(", "\uff09": ")",
			"\uff0b": "+", "\uff0e": ".",
			"\u30fb\u30fb\u30fb": "...", "\u3001": ",", "\uff0c": ",",
			"<<": "", ">>": "",
		};
		for (const k in repl) s = s.split(k).join(repl[k]);
		return s;
	};

	// ---- clear medal coefficient by image filename ----
	const MEDAL_COEF = {
		"rival_mark_per.png": 1.10,   // PERFECT ULTIMATE CHAIN
		"rival_mark_uc.png": 1.05,    // ULTIMATE CHAIN
		"rival_mark_comp_max.png": 1.04, // MAXXIVE COMP.
		"rival_mark_comp_ex.png": 1.02,  // EXCESSIVE COMP.
		"rival_mark_comp.png": 1.00,     // EFFECTIVE COMP.
		"rival_mark_play.png": 0.50,     // TRACK CRASH (not cleared)
	};

	// ---- grade coefficient derived from score ----
	const GRADE_TABLE = [
		[9900000, 1.05], // S
		[9800000, 1.02], // AAA+
		[9700000, 1.00], // AAA
		[9500000, 0.97], // AA+
		[9300000, 0.94], // AA
		[9000000, 0.91], // A+
		[8700000, 0.88], // A
		[7500000, 0.85], // B
		[6500000, 0.82], // C
		[0, 0.80],        // D
	];
	const gradeCoef = (score) => {
		for (const [th, coef] of GRADE_TABLE) if (score >= th) return coef;
		return 0.80;
	};

	// difficulty column -> master field mapping
	const DIFF_COLS = ["nov", "adv", "exh", "mxm", "inf", "ult"];
	const MASTER_KEY = { nov: "lv_nov", adv: "lv_adv", exh: "lv_exh", mxm: "lv_mxm", ult: "lv_ult" };
	// "inf" column's actual master key is whichever bonus-type key the song has (lv_GRV / lv_HVN / lv_VVD / lv_XCD / lv_INF / lv_NBL)
	const BONUS_KEYS = ["lv_GRV", "lv_HVN", "lv_VVD", "lv_XCD", "lv_INF", "lv_NBL"];

	const getMasterLv = (masterEntry, col) => {
		if (!masterEntry) return { lv: null, label: col };
		if (col === "inf") {
			for (const k of BONUS_KEYS) {
				if (masterEntry[k] != null) return { lv: masterEntry[k], label: k.replace("lv_", "") };
			}
			return { lv: null, label: col };
		}
		const key = MASTER_KEY[col];
		const v = masterEntry[key];
		return { lv: v == null ? null : v, label: col };
	};

	const parseMusicPage = (html, masterMap, results) => {
		const doc = new DOMParser().parseFromString(html, "text/html");
		const rows = doc.querySelectorAll("#pc-list table tbody tr.data_col");
		rows.forEach((tr) => {
			const titleEl = tr.querySelector("td.music div.title a");
			if (!titleEl) return;
			const musicName = titleEl.textContent.replace(/\u00a0/g, " ").replace(/\(EXIT TUNES\)\s*$/i, "").trim();
			const href = titleEl.getAttribute("href") || "";
			const musicId = (href.match(/music_id=([^&]+)/) || [])[1] || null;
			const masterEntry = masterMap.get(normTitle(musicName));

			DIFF_COLS.forEach((col) => {
				const td = tr.querySelector(`td.${col}`);
				if (!td) return;
				const imgs = td.querySelectorAll("img");
				if (imgs.length === 0) return; // chart doesn't exist for this song

				const medalSrc = imgs[0].getAttribute("src") || "";
				const medalFile = medalSrc.split("/").pop();
				if (medalFile === "rival_mark_no.png") return; // unplayed
				const medalCoef = MEDAL_COEF[medalFile];
				if (medalCoef === undefined) return; // unknown medal, skip defensively

				// score is the text node right after <br>, e.g. "10000000"
				const scoreText = (td.textContent.match(/(\d{5,8})/) || [])[1];
				if (!scoreText) return;
				const score = parseInt(scoreText, 10);
				if (!score) return;

				const lvInfo = getMasterLv(masterEntry, col);
				if (lvInfo.lv == null) return; // couldn't resolve level, skip rather than guess

				const grade = gradeCoef(score);
				const force = Math.floor(lvInfo.lv * (score / 10000000) * grade * medalCoef * 20);

				results.push({
					music: musicName,
					musicId,
					col,
					diff: lvInfo.label,
					lv: lvInfo.lv, score, grade, medalCoef, force,
				});
			});
		});
	};

	const DIFF_COLORS = {
		NOV: "#6a5acd", ADV: "#c98a00", EXH: "#d32f2f", MXM: "#757575",
		INF: "#e91e8c", GRV: "#ff8c00", HVN: "#29b6f6", VVD: "#e91e63",
		XCD: "#2979ff", NBL: "#4caf50", ULT: "#a6873a",
	};

	const COL_TO_BOXID = { nov: "novice", adv: "advanced", exh: "exhaust", mxm: "maximum", inf: "infinite", ult: "ultimate" };

	const DETAIL_PATH = "musicdata/data_detail.html";

	const fetchJacket = async (musicId, col) => {
		try {
			const html = await fetchHTML(`${BASE_URL}${DETAIL_PATH}?music_id=${musicId}`, BASE_URL + MUSIC_PATH);
			const doc = new DOMParser().parseFromString(html, "text/html");
			const boxId = COL_TO_BOXID[col];
			const box = boxId ? doc.querySelector(`#${boxId}.music_box, div.music_box#${boxId}`) : null;
			const img = (box || doc).querySelector(".jacket_area img");
			if (!img) return null;
			const src = img.getAttribute("src") || "";
			if (!src) return null;
			return new URL(src, location.origin).href;
		} catch (e) {
			return null;
		}
	};

	const loadHtml2Canvas = () => {
		if (window.html2canvas) return Promise.resolve(true);
		return new Promise((resolve) => {
			const s = document.createElement("script");
			s.src = "https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js";
			s.onload = () => resolve(true);
			s.onerror = () => resolve(false);
			document.head.appendChild(s);
		});
	};

	const buildShareCard = (volforce, top50) => {
		const COLS = 5;
		const cellsHtml = top50.map((r, i) => {
			const diffLabel = r.diff.toUpperCase();
			const diffColor = DIFF_COLORS[diffLabel] || "#1a6fb0";
			return `
			<div style="border:1px solid #dfe6df;border-radius:6px;padding:8px;background:#fff;display:flex;flex-direction:column;gap:4px;min-width:0;">
				<div style="display:flex;align-items:center;gap:8px;">
					<img src="${r.jacket || ""}" style="width:38px;height:38px;object-fit:cover;border-radius:4px;background:#eee;flex-shrink:0;">
					<div style="min-width:0;">
						<div style="font-size:21px;font-weight:bold;color:#2a5d34;line-height:1.1;">${r.force}</div>
						<div style="font-size:10px;color:#9aa;">#${i + 1}</div>
					</div>
				</div>
				<div style="font-size:10.5px;font-weight:bold;color:${diffColor};white-space:nowrap;">${diffLabel} ${r.lv} ・ ${r.score.toLocaleString()}</div>
				<div style="font-size:11px;color:#222;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${r.music}</div>
			</div>`;
		}).join("");

		const card = document.createElement("div");
		card.id = "__vf_share_card";
		card.style.cssText = "width:1120px;background:#eef3ee;font-family:-apple-system,'Hiragino Kaku Gothic ProN',sans-serif;color:#111;border-radius:14px;overflow:hidden;";
		card.innerHTML = `
			<div style="padding:20px 26px;background:#2a5d34;color:#fff;display:flex;justify-content:space-between;align-items:baseline;">
				<div>
					<div style="font-size:14px;letter-spacing:.08em;opacity:.9;">SOUND VOLTEX EXCEED GEAR</div>
					<div style="font-size:15px;letter-spacing:.05em;margin-top:2px;opacity:.9;">VOLFORCE(旧基準) 対象楽曲一覧</div>
				</div>
				<div style="font-size:46px;font-weight:bold;">${volforce.toFixed(3)}</div>
			</div>
			<div style="padding:16px;display:grid;grid-template-columns:repeat(${COLS},1fr);gap:8px;">
				${cellsHtml}
			</div>
			<div style="padding:6px 20px 14px;text-align:right;font-size:10px;color:#889;background:#eef3ee;">generated by SDVX VF Top50 tool</div>
		`;
		return card;
	};

	const saveCardAsImage = async (cardEl, statusEl) => {
		statusEl.textContent = "画像を生成中...";
		const ok = await loadHtml2Canvas();
		if (!ok || !window.html2canvas) {
			statusEl.textContent = "画像生成ライブラリの読み込みに失敗しました。";
			return;
		}
		try {
			const canvas = await window.html2canvas(cardEl, { backgroundColor: "#ffffff", scale: 2, useCORS: true });
			const url = canvas.toDataURL("image/png");
			const a = document.createElement("a");
			a.href = url;
			a.download = "sdvx_volforce_all.png";
			document.body.appendChild(a);
			a.click();
			a.remove();
			statusEl.textContent = "画像を保存しました。";
		} catch (e) {
			console.error(e);
			statusEl.textContent = "画像の生成に失敗しました。";
		}
	};

	const showOverlay = (volforce, top50) => {
		const bg = document.createElement("div");
		bg.style.cssText = "position:fixed;inset:0;z-index:100000;background:rgba(255,255,255,.97);overflow:auto;padding:10px;box-sizing:border-box;font-family:-apple-system,'Hiragino Kaku Gothic ProN',sans-serif;color:#111;";
		const rowsHtml = top50.map((r, i) => {
			const diffLabel = r.diff.toUpperCase();
			const diffColor = DIFF_COLORS[diffLabel] || "#1a6fb0";
			return `
			<tr style="background:${i % 2 === 0 ? "#ffffff" : "#f1f1f1"};">
				<td style="padding:6px 4px;text-align:center;color:#666;border-bottom:1px solid #ddd;">${i + 1}</td>
				<td style="padding:4px;text-align:center;border-bottom:1px solid #ddd;">${r.jacket ? `<img src="${r.jacket}" style="width:40px;height:40px;object-fit:cover;border-radius:3px;display:block;margin:0 auto;">` : ""}</td>
				<td style="padding:6px 6px;max-width:130px;overflow-wrap:break-word;border-bottom:1px solid #ddd;">${r.music}</td>
				<td style="padding:6px 4px;text-align:center;color:${diffColor};font-weight:bold;border-bottom:1px solid #ddd;">${diffLabel}</td>
				<td style="padding:6px 4px;text-align:center;border-bottom:1px solid #ddd;">${r.lv}</td>
				<td style="padding:6px 4px;text-align:right;border-bottom:1px solid #ddd;">${r.score.toLocaleString()}</td>
				<td style="padding:6px 6px;text-align:right;font-weight:bold;color:#c0752a;border-bottom:1px solid #ddd;">${r.force}</td>
			</tr>`;
		}).join("");

		bg.innerHTML = `
			<div style="max-width:640px;margin:0 auto;background:#fff;border:1px solid #ccc;border-radius:10px;box-shadow:0 4px 24px rgba(0,0,0,.15);overflow:hidden;">
				<div style="padding:14px 16px;background:linear-gradient(90deg,#3d8a4a,#52a35f);color:#fff;">
					<div style="font-size:12px;letter-spacing:.05em;">VOLFORCE(旧基準)</div>
					<div style="font-size:26px;font-weight:bold;">${volforce.toFixed(3)}</div>
				</div>
				<div style="max-height:65vh;overflow:auto;">
				<table style="width:100%;border-collapse:collapse;font-size:12.5px;table-layout:fixed;">
					<colgroup>
						<col style="width:24px;"><col style="width:44px;"><col><col style="width:40px;">
						<col style="width:28px;"><col style="width:74px;"><col style="width:52px;">
					</colgroup>
					<thead style="position:sticky;top:0;">
						<tr style="background:#eef3ee;color:#111;">
							<th style="padding:8px 4px;font-weight:normal;font-size:11px;border-bottom:2px solid #ccc;white-space:nowrap;">#</th>
							<th style="padding:8px 4px;font-weight:normal;font-size:11px;border-bottom:2px solid #ccc;"></th>
							<th style="padding:8px 6px;text-align:left;font-weight:normal;font-size:11px;border-bottom:2px solid #ccc;white-space:nowrap;">曲名</th>
							<th style="padding:8px 4px;font-weight:normal;font-size:11px;border-bottom:2px solid #ccc;white-space:nowrap;">難易度</th>
							<th style="padding:8px 4px;font-weight:normal;font-size:11px;border-bottom:2px solid #ccc;white-space:nowrap;">Lv</th>
							<th style="padding:8px 4px;text-align:right;font-weight:normal;font-size:11px;border-bottom:2px solid #ccc;white-space:nowrap;">スコア</th>
							<th style="padding:8px 6px;text-align:right;font-weight:normal;font-size:11px;border-bottom:2px solid #ccc;white-space:nowrap;">VF値</th>
						</tr>
					</thead>
					<tbody>${rowsHtml}</tbody>
				</table>
				</div>
				<div style="padding:10px 16px;background:#fff;border-top:1px solid #ddd;">
					<button id="__vf_save" style="width:100%;padding:10px;font-size:14px;background:#2a5d34;color:#fff;border:none;border-radius:6px;margin-bottom:8px;">全曲を画像として保存(SNS投稿用)</button>
					<div id="__vf_status" style="font-size:11px;color:#666;text-align:center;min-height:14px;margin-bottom:6px;"></div>
					<button id="__vf_close" style="width:100%;padding:10px;font-size:14px;background:#3d8a4a;color:#fff;border:none;border-radius:6px;">閉じる</button>
				</div>
			</div>`;
		document.body.appendChild(bg);

		// share card is rendered off-screen (not scaled/clipped by the overlay's own layout) so html2canvas captures it cleanly
		const shareCard = buildShareCard(volforce, top50);
		shareCard.style.position = "fixed";
		shareCard.style.left = "-9999px";
		shareCard.style.top = "0";
		document.body.appendChild(shareCard);

		const statusEl = bg.querySelector("#__vf_status");
		bg.querySelector("#__vf_save").addEventListener("click", () => saveCardAsImage(shareCard, statusEl));
		bg.querySelector("#__vf_close").addEventListener("click", () => { shareCard.remove(); bg.remove(); });
	};

	// ---- page guard (same as original tool) ----
	const processFlag = location.href.match(/\/\/p\.eagate\.573\.jp\/game\/sdvx\/vii\/playdata\/(|profile\/|profile\/index\.html|index\.html)(\?.*)?$/);
	if (!processFlag) {
		if (window.confirm("このページでは実行できません。SOUND VOLTEX の PLAYDATA プロフィールのページに移動します。")) {
			location.href = BASE_URL;
		}
		return;
	}

	if (!window.confirm("VF対象楽曲を表示します。ページが自動で遷移するまでこのままお待ち下さい。")) return;

	const overlayBg = document.createElement("div");
	overlayBg.style.cssText = "position:fixed;top:0;z-index:99999;width:100%;padding:6px;background:#52863C;color:#fff;font-family:sans-serif;";
	overlayBg.textContent = "データ取得中...";
	document.body.appendChild(overlayBg);

	try {
		// fetch master JSON in parallel with the e-amusement pages
		const masterPromise = fetch(MASTER_URL, { cache: "no-store" }).then((r) => r.json());

		overlayBg.textContent = "プロフィールデータ取得中...";
		await fetchHTML(BASE_URL + PLAYER_PATH, BASE_URL + INDEX_PATH);

		overlayBg.textContent = "楽曲データのページ一覧を取得中...";
		const musicIndexHTML = await fetchHTML(BASE_URL + MUSIC_PATH, BASE_URL + PLAYER_PATH);
		if (musicIndexHTML.indexOf("e-amusement") !== -1 && musicIndexHTML.indexOf("ベーシックコース") !== -1 && musicIndexHTML.indexOf("必要です") !== -1) {
			overlayBg.textContent = "楽曲データの取得に失敗しました(ベーシックコース未加入の可能性があります)。";
			return;
		}

		const masterList = await masterPromise;
		const masterMap = new Map();
		masterList.forEach((m) => masterMap.set(normTitle(m.music), m));

		const parser = new DOMParser();
		const doc = parser.parseFromString(musicIndexHTML, "text/html");
		const select = doc.querySelector("#search_page");
		const maxPage = select && select.options.length > 0 ? Number(select.options[select.options.length - 1].value) + 1 : 2;

		const results = [];
		parseMusicPage(musicIndexHTML, masterMap, results);

		for (let k = 2; k < maxPage; k++) {
			overlayBg.textContent = `楽曲データ取得中... (${k}/${maxPage - 1})`;
			const pageHTML = await getMusicData(k);
			parseMusicPage(pageHTML, masterMap, results);
			await _sleep(getRandomInt(600, 1100));
		}

		results.sort((a, b) => b.force - a.force);
		const top50 = results.slice(0, 50);
		const volforce = top50.reduce((sum, r) => sum + r.force, 0) / 1000;

		overlayBg.textContent = "ジャケット画像を取得中...";
		const uniqueKeys = [...new Set(top50.filter((r) => r.musicId).map((r) => `${r.musicId}::${r.col}`))];
		const jacketMap = new Map();
		for (const key of uniqueKeys) {
			const [musicId, col] = key.split("::");
			jacketMap.set(key, await fetchJacket(musicId, col));
			await _sleep(getRandomInt(300, 600));
		}
		top50.forEach((r) => { r.jacket = r.musicId ? jacketMap.get(`${r.musicId}::${r.col}`) : null; });

		overlayBg.remove();
		showOverlay(volforce, top50);
	} catch (error) {
		console.error("Error:", error);
		overlayBg.textContent = "エラーが発生しました。";
	}
})();
